const input = $input.first().json;
const body = input.body ?? input;
if (typeof body.chatInput !== 'string' || !body.chatInput.trim()) throw new Error('Campo chatInput ausente.');
let request;
try { request = JSON.parse(body.chatInput); } catch { throw new Error('chatInput deve conter JSON valido.'); }
const tasks = ['create_operational_procedure', 'answer_procedure_question', 'conduct_operational_interview', 'create_operational_policy', 'build_area_reference', 'send_notification', 'sap_bigquery_check', 'sap_automation_assessment', 'extract_document_dates', 'build_as_is_flow'];
if (request.task === 'sap_bigquery_check') {
  // So parametros de listas fechadas (nunca SQL livre); mesmas regras do app (SAP_COLUMNS, SAP_TEXT_COLUMNS, SAP_DATE_FIELDS).
  const COLUNAS = { tcode: /^[A-Z0-9\/_-]{2,20}$/, bukrs: /^[A-Z0-9]{4}$/, blart: /^[A-Z0-9]{2}$/, usnam: /^[A-Z0-9._-]{2,12}$/, waers: /^[A-Z]{3}$/, awtyp: /^[A-Z0-9]{3,5}$/, glvor: /^[A-Z0-9]{4}$/, bstat: /^[A-Z0-9]$/, gjahr: /^\d{4}$/, monat: /^\d{1,2}$/ };
  const TEXTO = ['xblnr', 'bktxt'], DATAS = ['budat', 'bldat', 'cpudt'];
  const coluna = k => Object.prototype.hasOwnProperty.call(COLUNAS, k);
  const falha = m => { throw new Error('Consulta SAP invalida: ' + m); };
  let c = request.consulta;
  if (!c) {
    // Verificacao padrao do app: documentos das transacoes nos ultimos N dias (ate 30).
    const codes = Array.isArray(request.tcodes) ? request.tcodes.map(x => String(x).toUpperCase()) : [];
    if (!codes.length || codes.length > 15) throw new Error('Transacoes SAP invalidas.');
    const dias = Math.min(Math.max(parseInt(request.dias || 30, 10) || 30, 1), 30);
    const dia = t => new Date(t).toISOString().slice(0, 10);
    c = { inicio: dia(Date.now() - dias * 864e5), fim: dia(Date.now()), campo_data: 'budat', colunas: ['tcode'], filtros: { tcode: codes }, contem: {} };
  }
  const iso = /^\d{4}-\d{2}-\d{2}$/;
  if (!iso.test(String(c.inicio)) || !iso.test(String(c.fim))) falha('datas');
  const ini = Date.parse(c.inicio + 'T00:00:00Z'), fim = Date.parse(c.fim + 'T00:00:00Z');
  if (!(ini <= fim) || (fim - ini) / 864e5 > 30 || c.inicio < '2024-12-01' || fim > Date.now() + 864e5) falha('periodo (ate 30 dias, a partir de 01/12/2024)');
  if (!DATAS.includes(c.campo_data)) falha('campo de data');
  const colunas = [...new Set((Array.isArray(c.colunas) ? c.colunas : []).map(x => String(x).toLowerCase()))];
  if (!colunas.length || colunas.length > 4 || colunas.some(x => !coluna(x))) falha('colunas');
  const filtros = {};
  for (const [k, v] of Object.entries(c.filtros || {})) {
    const lista = [...new Set((Array.isArray(v) ? v : []).map(x => String(x).trim().toUpperCase()).filter(Boolean))];
    if (!coluna(k) || lista.length > 20 || lista.some(x => !COLUNAS[k].test(x))) falha('filtro ' + k);
    if (lista.length) filtros[k] = lista;
  }
  const contem = {};
  for (const [k, v] of Object.entries(c.contem || {})) {
    const t = String(v || '').replace(/\s+/g, ' ').trim().toUpperCase();
    if (!TEXTO.includes(k) || (t && !/^[A-Z0-9 .\/-]{3,30}$/.test(t))) falha('texto ' + k);
    if (t) contem[k] = t;
  }
  return [{ json: { sessionId: body.sessionId || 'sap', request: { task: 'sap_bigquery_check', solicitante: String(request.solicitante || '').slice(0, 254), consulta: { inicio: c.inicio, fim: c.fim, campo_data: c.campo_data, colunas, filtros, contem } } } }];
}
//;
if (request.task === 'send_notification') {
  const to = String(request.to || '').split(',').map(s => s.trim()).filter(Boolean);
  // Seguranca (05/11/2026): so destinatarios do Grupo SBF (quem tem a senha do webhook nao manda e-mail como Vektor para fora).
  if (!to.length || to.length > 20 || to.some(e => !/^[a-z0-9._%+-]+@(partner\.)?gruposbf\.com\.br$/i.test(e))) throw new Error('Destinatarios invalidos (so e-mails do Grupo SBF: @example.com ou @partner.example.com).');
  if (typeof request.subject !== 'string' || !request.subject.trim() || typeof request.html !== 'string' || !request.html.trim()) throw new Error('Aviso sem assunto ou texto.');
  return [{ json: { sessionId: body.sessionId || 'aviso', request: { task: 'send_notification', to: to.join(', '), subject: request.subject.slice(0, 250), html: request.html.slice(0, 100000), drive_lookup: /^[A-Z]{2,3}-\d{2}\.\d{3}\.\d{3}-\d+$/.test(request.drive_lookup || '') ? request.drive_lookup : '', drive_search_url: String(request.drive_search_url || '').startsWith('https://drive.google.com/drive/search?q=') ? request.drive_search_url : '' } } }];
}
if (request.task === 'build_area_reference' && (typeof request.area !== 'string' || !request.area.trim())) throw new Error('Area nao informada.');
if (!tasks.includes(request.task)) throw new Error('Tarefa nao reconhecida.');
if (request.task === 'build_as_is_flow' && (!request.document || typeof request.document.text !== 'string' || !request.document.text.trim() || !Array.isArray(request.requirements))) throw new Error('Documento invalido para o fluxo As Is.');
if (['create_operational_procedure', 'create_operational_policy'].includes(request.task) && (!request.questionnaire || !Array.isArray(request.requirements))) throw new Error('Questionario invalido.');
if (request.task === 'answer_procedure_question' && (typeof request.question !== 'string' || !Array.isArray(request.knowledge_base))) throw new Error('Pergunta ou base documental invalida.');
if (request.task === 'conduct_operational_interview' && (!request.questionnaire || !Array.isArray(request.conversation_history))) throw new Error('Entrevista sem questionario ou historico valido.');
const files = Array.isArray(request.reference_documents) ? request.reference_documents : [];
const binary = {};
let imageIndex = 0;
for (const file of files) {
  if (typeof file.image_data_url !== 'string') continue;
  const match = file.image_data_url.match(/^data:(image\/[a-zA-Z0-9.+-]+);base64,([A-Za-z0-9+/=]+)$/);
  if (!match) throw new Error(`Imagem em formato invalido: ${file.filename || 'anexo'}`);
  const mimeType = match[1].toLowerCase();
  const ext = mimeType.split('/')[1].replace('jpeg', 'jpg');
  const fileName = file.filename || `anexo-visual-${imageIndex + 1}.${ext}`;
  binary[`image${imageIndex}`] = { data: match[2], mimeType, fileName };
  imageIndex += 1;
}
const sanitizedRequest = {
  ...request,
  reference_documents: files.map(({ image_data_url, ...metadata }) => metadata),
};
return [{ json: { sessionId: body.sessionId || request.record_id || 'sem-sessao', request: sanitizedRequest }, ...(Object.keys(binary).length ? { binary } : {}) }];

// Monta o e-mail no formato da API do Gmail (RFC 2822, base64url), com remetente Vektor.
// A conta conectada na credencial precisa ter admin@example.com em "Enviar e-mail como" (alias verificado);
// sem isso, o Gmail troca o remetente pela propria conta conectada.
const FROM_NAME = 'Vektor';
const FROM_EMAIL = 'admin@example.com';
const r = $('É aviso por e-mail?').first().json.request;
const found = (($input.first().json || {}).files || [])[0];
// Link direto do PDF no Drive no lugar do link de busca pelo codigo (quando o arquivo foi encontrado).
const html = found && found.webViewLink && r.drive_search_url ? r.html.split(r.drive_search_url).join(found.webViewLink) : r.html;
const b64 = s => Buffer.from(String(s), 'utf8').toString('base64');
const mime = [
  `From: ${FROM_NAME} <${FROM_EMAIL}>`,
  `To: ${r.to}`,
  `Subject: =?UTF-8?B?${b64(r.subject)}?=`,
  'MIME-Version: 1.0',
  'Content-Type: text/html; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
  '',
  b64(html).replace(/.{76}/g, '$&\r\n'),
].join('\r\n');
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: { raw, to: r.to, subject: r.subject } }];

// Resume o resultado (numeros agregados pelas colunas escolhidas). Erro do BigQuery volta como ok:false.
const itens = $input.all().map(i => i.json || {});
const linhas = itens.filter(j => j.documentos !== undefined && j.documentos !== null);
const erro = itens.map(j => j.error).find(Boolean);
return [{ json: erro && !linhas.length ? { ok: false, erro: String(erro.message || erro) } : { ok: true, linhas } }];
